import itertools

def is_costas(p):
    n = len(p)
    diffs = set()
    for i in range(n):
        for j in range(i + 1, n):
            diff = (j - i, p[j] - p[i])
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

def find_costas(n, fixed):
    # fixed is a dictionary {index: value}
    indices = [i for i in range(n) if i not in fixed]
    values = [v for v in range(n) if v not in fixed.values()]

    for p_vals in itertools.permutations(values):
        p = [0] * n
        for i, val in fixed.items():
            p[i] = val
        for i, val in zip(indices, p_vals):
            p[i] = val

        if is_costas(p):
            return p
    return None

fixed = {1: 1}
result = find_costas(7, fixed)
print(result)

